def roman_to_int(s: str) -> int:
    # 로마 숫자 기호와 해당 정수 값 매핑
    roman_values = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }

    total = 0
    n = len(s)

    for i in range(n):
        current_value = roman_values[s[i]]

        # 다음 문자가 존재하고 현재 값보다 크다면 뺄셈 표기(IV, IX 등)
        if i + 1 < n and current_value < roman_values[s[i + 1]]:
            total -= current_value
        else:
            total += current_value

    return total


# 테스트 예시
if __name__ == "__main__":
    test_cases = ["III", "IV", "IX", "LVIII", "MCMXCIV"]
    for case in test_cases:
        print(f"{case} -> {roman_to_int(case)}")
